# day index for each verse (0 = before the first day)
def day_of(ref):
    c, v = ref
    if c == 2: return 7
    if v <= 2: return 0
    for d, last in enumerate([5, 8, 13, 19, 23, 31], start=1):
        if v <= last: return d
    return 6
assert len(V) == 34
for ref, he, ph, en in V: assert len(he) == len(ph), ref
